import{_ as n,o as t,c as r,a2 as a}from"./chunks/framework.mRCPFc5l.js";const u=JSON.parse('{"title":"Spalten verwalten","description":"Spalten in einer Ansicht ausblenden, umsortieren und sperren.","frontmatter":{"title":"Spalten verwalten","description":"Spalten in einer Ansicht ausblenden, umsortieren und sperren."},"headers":[],"relativePath":"ansichten/spalten-verwalten.md","filePath":"ansichten/spalten-verwalten.md","lastUpdated":1786086822000}'),i={name:"ansichten/spalten-verwalten.md"};function s(l,e,d,o,h,c){return t(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="spalten-verwalten" tabindex="-1">Spalten verwalten <a class="header-anchor" href="#spalten-verwalten" aria-label="Permalink to &quot;Spalten verwalten&quot;">​</a></h1><p>Welche Spalten in welcher Reihenfolge erscheinen, legen Sie <strong>je Ansicht</strong> fest. Andere Ansichten desselben Grids bleiben unberührt.</p><div class="warning custom-block"><p class="custom-block-title">Ausblenden ist nicht Löschen</p><p>Eine ausgeblendete Spalte ist nur in dieser Ansicht unsichtbar. Die Daten bleiben vollständig erhalten und sind in jeder anderen Ansicht da.</p><p>Das Löschen einer Spalte entfernt dagegen die Werte aus <strong>allen</strong> Einträgen — endgültig.</p></div><h2 id="spalten-ausblenden" tabindex="-1">Spalten ausblenden <a class="header-anchor" href="#spalten-ausblenden" aria-label="Permalink to &quot;Spalten ausblenden&quot;">​</a></h2><ol><li>Klicken Sie in der Werkzeugleiste auf <strong>Ausblenden</strong>.</li><li>Schalten Sie einzelne Spalten aus.</li></ol><p>Sind Spalten ausgeblendet, zeigt die Werkzeugleiste das mit <strong>ausgeblendet</strong> an.</p><div class="tip custom-block"><p class="custom-block-title">Ansichten für unterschiedliche Aufgaben</p><p>Statt eine breite Tabelle horizontal zu scrollen, lohnen sich mehrere Ansichten mit je passendem Spaltensatz — „Bearbeitung&quot; mit allen Feldern, „Übersicht&quot; mit vier Spalten, „Für den Export&quot; mit genau den Feldern, die in die CSV sollen.</p></div><h2 id="spalten-umsortieren" tabindex="-1">Spalten umsortieren <a class="header-anchor" href="#spalten-umsortieren" aria-label="Permalink to &quot;Spalten umsortieren&quot;">​</a></h2><p>Über <strong>Weitere</strong> (⋮) → <strong>Spalten neu anordnen</strong>. Der Hinweis lautet <em>Spalten per Drag &amp; Drop neu anordnen</em>.</p><div class="tip custom-block"><p class="custom-block-title">Wichtiges nach links</p><p>Die ersten zwei bis drei Spalten sind das, was Nutzer zuerst sehen — und in einem eingebetteten <a href="/seiten/portal-veroeffentlichen">Portal</a> auf schmalen Bildschirmen manchmal das Einzige. Stellen Sie dorthin, was den Eintrag identifiziert.</p></div><h2 id="spalten-sperren" tabindex="-1">Spalten sperren <a class="header-anchor" href="#spalten-sperren" aria-label="Permalink to &quot;Spalten sperren&quot;">​</a></h2><p>Über das Menü im Spaltenkopf: <strong>Spalte in dieser Ansicht sperren</strong>. Danach zeigt die Spalte den Hinweis <em>Spalte ist in dieser Ansicht gesperrt</em>; über <strong>Spalte in dieser Ansicht entsperren</strong> nehmen Sie es zurück.</p><p>Eine gesperrte Spalte ist sichtbar, aber in dieser Ansicht nicht bearbeitbar.</p><div class="tip custom-block"><p class="custom-block-title">Wofür sich das Sperren eignet</p><p>Für Ansichten, die andere Menschen benutzen, ohne dass sie bestimmte Felder ändern sollen — etwa eine geteilte Ansicht, in der Preise sichtbar, aber nicht änderbar sein sollen.</p><p><strong>Das ist kein Zugriffsschutz</strong>, sondern ein Schutz vor Versehen: Die Sperre gilt je Ansicht, und wer eine andere Ansicht öffnet, kann das Feld dort bearbeiten. Für echte Beschränkungen dienen <a href="/zusammenarbeit/rollen">Rollen</a> und <a href="/zusammenarbeit/zugriff-beschraenken">Zugriffsbeschränkungen</a>.</p></div><h2 id="spalte-umbenennen-und-beschreiben" tabindex="-1">Spalte umbenennen und beschreiben <a class="header-anchor" href="#spalte-umbenennen-und-beschreiben" aria-label="Permalink to &quot;Spalte umbenennen und beschreiben&quot;">​</a></h2><p>Über das Menü im Spaltenkopf:</p><table tabindex="0"><thead><tr><th>Aktion</th><th>Wirkung</th></tr></thead><tbody><tr><td><strong>Feld bearbeiten</strong></td><td>Öffnet <strong>Spaltenname</strong> und <strong>Spaltentyp</strong></td></tr><tr><td><strong>Spaltenbeschreibung bearbeiten</strong></td><td>Erklärender Text zum Feld</td></tr><tr><td><strong>Feldkey verwalten</strong></td><td>Technischer Bezeichner des Feldes</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Name und Typ gelten für das ganze Grid</p><p>Anders als Ausblenden und Sortieren wirken diese Änderungen <strong>überall</strong> — in allen Ansichten, Formularen und Flows.</p><p>Ein Umbenennen ist unkritisch, weil intern nicht über den Namen verwiesen wird. Eine Typänderung kann dagegen Werte verlieren. → <a href="/grids/grid-anlegen">Ihr erstes Grid</a></p></div><div class="tip custom-block"><p class="custom-block-title">Beschreibungen sparen Rückfragen</p><p>Die Spaltenbeschreibung erscheint auch in <a href="/formulare/felder-konfigurieren">Formularen</a> als Hilfetext unter dem Feld. Ein Satz zu „Was gehört hier rein&quot; reduziert Fehleingaben spürbar — besonders bei Feldern, die andere Menschen ausfüllen.</p></div><h2 id="summenzeile" tabindex="-1">Summenzeile <a class="header-anchor" href="#summenzeile" aria-label="Permalink to &quot;Summenzeile&quot;">​</a></h2><p>Unter numerischen Spalten lässt sich eine <strong>Summe</strong> über alle sichtbaren Einträge einblenden. Sie berücksichtigt den aktiven Filter.</p><p>Verfügbar bei <strong>Zahl</strong>, <strong>Kommazahl</strong> und <strong>Währung</strong>.</p><h2 id="leere-ansicht-anpassen" tabindex="-1">Leere Ansicht anpassen <a class="header-anchor" href="#leere-ansicht-anpassen" aria-label="Permalink to &quot;Leere Ansicht anpassen&quot;">​</a></h2><p>Über <strong>Weitere</strong> (⋮) → <strong>Leere Ansicht bearbeiten</strong> ändern Sie den Text, der erscheint, wenn keine Einträge sichtbar sind — voreingestellt <em>Keine Ergebnisse gefunden</em>.</p><div class="tip custom-block"><p class="custom-block-title">Nützlich in Portalen</p><p>In einem veröffentlichten Portal ist „Keine Ergebnisse gefunden&quot; wenig hilfreich. Ein Text wie „Für diesen Zeitraum liegen noch keine Buchungen vor&quot; erklärt Besuchern, was los ist.</p></div><p>→ <a href="/ansichten/leerzustand">Leerzustand anpassen</a></p><h2 id="was-noch-zur-ansicht-gehort" tabindex="-1">Was noch zur Ansicht gehört <a class="header-anchor" href="#was-noch-zur-ansicht-gehort" aria-label="Permalink to &quot;Was noch zur Ansicht gehört&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Einstellung</th><th>Gilt für</th></tr></thead><tbody><tr><td>Ausgeblendete Spalten, Reihenfolge, Sperren</td><td>nur diese Ansicht</td></tr><tr><td>Leerzustand-Text</td><td>nur diese Ansicht</td></tr><tr><td>Spaltenname, Typ, Beschreibung, Feldkey</td><td>das ganze Grid</td></tr></tbody></table><h2 id="weiter" tabindex="-1">Weiter <a class="header-anchor" href="#weiter" aria-label="Permalink to &quot;Weiter&quot;">​</a></h2><ul><li><a href="/ansichten/filtern-sortieren-gruppieren">Filtern, Sortieren, Gruppieren</a></li><li><a href="/ansichten/ansicht-teilen">Ansicht teilen</a></li><li><a href="/referenz/spaltentypen">Spaltentypen-Referenz</a></li></ul>',30)])])}const b=n(i,[["render",s]]);export{u as __pageData,b as default};
